"""简历挖掘出的话术（13–27）。"""
MORE = [{'n': '13', 'scene_zh': '多平台订单（京东/苏宁/政采云）怎么统一', 'scene_en': 'One order model for many platforms', 'junior': '「每个平台写一套接口，京东走京东的，苏宁走苏宁的，if else 判断一下。」', 'senior': '先抽象一个统一订单模型：渠道、渠道单号、买家、商品行、金额、状态。每个渠道一个适配器，只做三件事——拉单、映射到统一模型、回传结果；状态以我们的状态机为准，渠道状态只是映射输入。新增一个平台只加一个适配器，主流程一行不改。', 'keywords': ['统一订单模型', '适配器', '状态机', '渠道单号唯一键', '主流程不改'], 'why': ['先说<b>模型</b>再说模式名，面试官立刻知道你想过扩展。', '「只做三件事」是<b>边界感</b>：适配器不许碰业务规则。', '「主流程一行不改」是<b>开闭原则</b>的实际收益，比背概念有说服力。']}, {'n': '14', 'scene_zh': '50 万条政采云数据怎么爬', 'scene_en': 'Crawling half a million rows a day', 'junior': '「用 WebMagic 爬的，爬完存数据库，每天跑一次。」', 'senior': '按公告分类做分页种子，XXL-Job 分片广播把任务拆到多台执行器，每片自己限速，避免把对方站点打挂。入库按公告号唯一键 upsert，重复爬到不会多一行；单条失败进重试队列，第二天从上次的页码继续，不用从头再来。', 'keywords': ['分片广播', '限速', '唯一键 upsert', '失败重试', '断点续跑'], 'why': ['先讲<b>怎么拆开跑</b>（分片），再讲怎么不重复（upsert）。', '限速这句是在<b>替对方考虑</b>，做过生产的人才这么说。', '断点续跑讲的是<b>可靠性</b>，比「爬得多快」值钱。']}, {'n': '15', 'scene_zh': '微信 Native 支付整条链路', 'scene_en': 'WeChat Native pay, end to end', 'junior': '「调微信支付接口，成功了就发货。」', 'senior': '下单先落本地 PENDING 订单和唯一订单号，调统一下单拿 code_url 给前端出二维码。回调验签后三步：幂等表拦重复、状态 CAS 改 PAID、扣库存发货。最后再挂一个对账任务拉账单兜底，回调丢了也能补回来。', 'keywords': ['验签', '幂等表', '状态 CAS', '对账兜底', 'code_url'], 'why': ['按<b>时间顺序</b>讲链路，听完就知道你亲手做过。', '主动答「回调丢了怎么办」——这是<b>生产经验</b>的分界线。', '对账是加分项，多数人只讲到回调就停了。']}, {'n': '16', 'scene_zh': '多层级数据权限（集团→区域→站点）', 'scene_en': 'Data permission across group, region, station', 'junior': '「每个接口里判断当前用户是什么角色，再拼 where 条件。」', 'senior': '用 HandlerInterceptor 加自定义注解：注解上标这个接口管哪张表、哪个字段，拦截器解析当前用户的组织路径，统一拼成 where 条件注入到 SQL 里。业务代码一行权限判断都不写，新增接口只要加个注解。', 'keywords': ['自定义注解', '拦截器', '组织路径', '统一注入', '零侵入'], 'why': ['讲<b>统一出口</b>而不是「到处判断」，这是架构意识。', '零侵入意味着<b>不会漏</b>，漏一个接口就是数据事故。', '可以顺势延伸到行级权限、多租户，把话题带上你的主场。']}, {'n': '17', 'scene_zh': '列表接口 P95 从 800ms 降到 240ms', 'scene_en': 'P95 from 800ms to 240ms', 'junior': '「加了 Redis 缓存，快了很多。」', 'senior': '分两半看：读的一半是热点数据进 Redis，命中率 92%，数据库只承接 8% 的流量；写的一半是慢 SQL 治理，N+1 合成一次 join、补覆盖索引。两个瓶颈分开治，P95 从 800 降到 240。', 'keywords': ['命中率 92%', 'P95', 'N+1', '覆盖索引', '分开治'], 'why': ['数字带<b>口径</b>：P95、命中率，不说「快了好几倍」。', '主动拆成<b>读和写</b>两半，说明你不是只会上缓存。', '不把功劳全给缓存——面试官最烦「加了 Redis 就快了」。']}, {'n': '18', 'scene_zh': 'Redisson 分布式锁到底锁住了什么', 'scene_en': 'What the distributed lock really covers', 'junior': '「加个分布式锁，就不会重复扣库存了。」', 'senior': '锁只包临界区：读库存、判断、扣减、写回，几毫秒的数据库操作。key 用业务维度 lock:stock:{skuId}，不是订单号。持锁进程挂了靠 watchdog 停止续租、租约自然过期。所以锁是降冲突，最终正确性还是靠唯一索引和状态 CAS 兜底。', 'keywords': ['临界区', '业务维度 key', 'watchdog', '锁不是最终保障', 'CAS 兜底'], 'why': ['先划<b>边界</b>（只包几毫秒），再说 key 设计。', 'watchdog 要能说出<b>它续的是租约</b>，不是锁本身。', '承认锁会失效、要靠数据库兜底，这是<b>成熟度</b>。']}, {'n': '19', 'scene_zh': '百万级报表 3 秒内返回（Oracle）', 'scene_en': 'Million-row report under three seconds', 'junior': '「用了 Oracle 存储过程，比 Java 里查快。」', 'senior': '原来是 Java 里多次查询再内存聚合，改成一次存储过程把聚合下推到库内，走分区裁剪加覆盖索引。再把报表拆成「当日增量 + 历史汇总」，常态只算增量。3 秒是 P95，不是平均值。', 'keywords': ['下推', '分区裁剪', '覆盖索引', '增量+汇总', 'P95'], 'why': ['讲清<b>为什么快</b>（下推 + 裁剪），不是「存储过程就是快」。', '增量 + 汇总的思路可以复用到任何报表，<b>可迁移</b>。', '分清 P95 和平均值，一眼看出你真看过监控。']}, {'n': '20', 'scene_zh': '模板化表单引擎怎么设计', 'scene_en': 'Config-driven form engine', 'junior': '「每种表单写一个页面，改需求就改代码。」', 'senior': '表单结构存成 JSON：字段类型、校验、字典、布局；前端按 JSON 渲染，后端按 JSON 校验并落成「业务主表 + key-value 明细」。新增业务类型只配数据，不改代码。代价是查询要做行转列，我们用宽表加定时物化解决。', 'keywords': ['JSON 元数据', '配置驱动', '业务主表+明细', '行转列', '物化'], 'why': ['一句话讲清<b>配置驱动</b>：改数据不改代码。', '主动说<b>代价</b>（行转列、物化），这是真做过的标志。', '能顺带说出「哪些场景不适合」，可信度再上一层。']}, {'n': '21', 'scene_zh': 'Netty 撑 300+ 台售货机长连接', 'scene_en': 'Three hundred devices on Netty', 'junior': '「用 Netty 连设备，收数据存库。」', 'senior': '一条 TCP 长连接对应一台机器，编解码器处理粘包拆包——长度字段加魔数。心跳 30 秒，两个周期没回就判离线并告警；断线由设备侧重连，服务端用会话表恢复。指令下发查 Map<设备号, Channel>，写失败降级成待办队列，不丢指令。', 'keywords': ['粘包拆包', '心跳', '会话表', '断线重连', '降级为待办'], 'why': ['粘包拆包是<b>必问点</b>，主动说出来面试官就不追了。', '心跳 + 会话表讲的是<b>在线状态管理</b>，不是「连上了就行」。', '写失败降级成待办，说明你考虑过<b>指令不能丢</b>。']}, {'n': '22', 'scene_zh': 'UDP 组播收设备状态 + 链路智能切换', 'scene_en': 'Multicast telemetry and link switch', 'junior': '「用 UDP 收设备状态，收到就存库。」', 'senior': '设备状态是广播型数据，一份数据发给一组接收者，所以用组播而不是点对点，50 台设备只发一次。允许丢包——下一轮状态就覆盖了，所以不上 TCP 重传。链路切换是打分制：信号质量、带宽利用率、误码率加权，超过阈值才切，避免来回抖。', 'keywords': ['组播', '容忍丢包', '打分制', '加权阈值', '防抖'], 'why': ['先解释<b>为什么是组播</b>，而不是先说技术名。', '讲清「为什么可以不管丢包」，比背 UDP 特性有说服力。', '打分制 + 阈值防抖，是<b>工程判断</b>，不是教科书答案。']}, {'n': '23', 'scene_zh': '热搜榜怎么实时算（Redis 有序集合）', 'scene_en': 'Realtime trending list on Redis', 'junior': '「用 Redis 存热搜，定时刷新一下。」', 'senior': '阅读、评论、转发各给权重，分钟级增量累加到有序集合的 score；榜单直接 ZREVRANGE 取 Top N。过期靠分片 key，每小时一个，旧的分片自然淘汰，不用扫全量。热度做指数衰减，避免老新闻永远挂在榜上。', 'keywords': ['权重', 'ZSet 增量', 'ZREVRANGE', '分片 key', '指数衰减'], 'why': ['权重 + 增量是<b>算法层</b>，ZREVRANGE 是<b>实现层</b>，层次清楚。', '分片 key 解决过期，说明你算过<b>内存和淘汰</b>的账。', '指数衰减一句话，就把「老新闻霸榜」的坑补上了。']}, {'n': '24', 'scene_zh': '基于若依二次开发，怎么讲不显low', 'scene_en': 'Talking about building on a framework', 'junior': '「基于若依改的，其实没什么技术含量。」', 'senior': '框架给的是骨架：权限、字典、代码生成。我们在上面做了三件事：认证链改成多端统一（JWT + 拦截器）、数据权限做成注解驱动的行级过滤、供应商侧独立出准入与结算域。骨架省掉 60% 的样板代码，剩下的全是业务域建模。', 'keywords': ['骨架', '业务域建模', '认证链', '注解驱动行级', '省 60% 样板'], 'why': ['先<b>承认框架的价值</b>，再讲你加的东西，姿态稳。', '「剩下的全是业务域建模」把话题拉回你的强项。', '别贬低自己用过的框架，面试官会怀疑你<b>看不起业务</b>。']}, {'n': '25', 'scene_zh': '十秒自我介绍（十年经验）', 'scene_en': 'Ten-second self introduction', 'junior': '「我有十年经验，做过很多项目，什么都能干。」', 'senior': '我做了十年 Java，一直做 B 端：订单与支付链路、燃气采购的资源与权限、设备侧长连接监控。最近两年在订单系统上把日单量从 3000 做到 7500，支付链路做到可回调、可对账。这套东西换到你们的业务里，基本能直接用。', 'keywords': ['B 端', '支付链路', '权限', '可对账', '直接可用'], 'why': ['先说<b>领域</b>再说年限，十年是背景不是卖点。', '一个<b>数字</b>胜过十个形容词（3000 → 7500）。', '结尾落到「对你们能直接用」，把自我介绍变成<b>解决方案</b>。']}, {'n': '26', 'scene_zh': '空档期 / 为什么离职', 'scene_en': 'The gap and the last job', 'junior': '「上一家不干了，休息了一阵。」', 'senior': '上一段项目今年 8 月收尾，我离职后两个月没闲着：把支付幂等、订单状态机、缓存一致性这几块重新梳理了一遍，也写了小工具做验证。现在找的是能长期做的 B 端业务，不想再频繁换。', 'keywords': ['项目收尾', '主动补齐', '可验证', '长期'], 'why': ['给空档一个<b>具体内容</b>，而不是「休息」。', '「可验证」很关键——说学了什么，最好有东西能看。', '结尾说<b>稳定性</b>，正面回应招聘方最担心的事。']}, {'n': '27', 'scene_zh': '你最大的缺点是什么', 'scene_en': 'Your biggest weakness', 'junior': '「我比较追求完美，做事太认真。」', 'senior': '我容易一头扎进实现，需求边界没确认就开工，有一次因此返工。现在开工前先写三行：谁用、什么场景、验收标准是什么，跟业务对一遍再动手。', 'keywords': ['真实事例', '根因', '机制化改进'], 'why': ['「追求完美」是<b>套话</b>，面试官听腻了。', '给一个<b>真实但不致命</b>的缺点，再给已落地的改法。', '重点在「现在怎么做」，展示<b>复盘能力</b>。']}]
